#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Cliplink production setup and cutover (ticket #9, spec #1).
#   scripts/cutover.sh            the whole walk, from OAuth apps to the smoke check
#   scripts/cutover.sh rollback   only the rollback steps
# Production values are saved to .env.cutover (gitignored, mode 0600) so a re-run can
# resume. Development OAuth values go to .env. Old production env vars are backed up to
# .env.cutover-backup for rollback. Delete both files once the old system is torn down.

PROD_URL="https://cliplink.app"
NEW_REPO="ososuna/cliplink"
SPEC_BRANCH="spec/one-astro-app"
BACKUP_FILE=".env.cutover-backup"
LEGACY_VARS=(PUBLIC_API_BASE_URL PUBLIC_API_DOMAIN PUBLIC_APP_DOMAIN PUBLIC_APP_NAME)
TMP_DIR=$(mktemp -d)
trap 'rm -rf "$TMP_DIR"' EXIT

# verify ARGS runs a check from scripts/cutover/verify.ts.
verify() { node scripts/cutover/verify.ts "$@"; }

# pull_env TARGET prints the path of a temp file holding that Vercel environment.
pull_env() {
  local file="$TMP_DIR/$1.env"
  rm -f "$file" # pull merges into an existing file
  vercel env pull "$file" --environment "$1" --yes >/dev/null 2>&1 \
    || { warn "vercel env pull --environment $1 failed" >&2; return 1; }
  printf '%s' "$file"
}

# check_env TARGET pulls that environment and checks it. Fails on any problem.
check_env() {
  local file
  file=$(pull_env "$1") || return 1
  verify env "$1" "$file"
}

# check_neon_env passes once the Neon integration has set production's database URLs.
check_neon_env() {
  local file
  file=$(pull_env production) || return 1
  grep -qE '^DATABASE_URL=' "$file" && grep -qE '^DATABASE_URL_UNPOOLED=' "$file"
}

# vercel_env NAME TARGET VALUE [sensitive] adds or replaces one variable.
vercel_env() {
  local flags=(--environment "$2" --value "$3" --force --yes)
  [[ "${4:-}" == sensitive ]] && flags+=(--sensitive)
  if [[ -z "$3" ]]; then
    SKIPPED+=("Vercel env $1 for $2 (no value: re-run the OAuth stages)")
    warn "no value for $1 ($2), skipped"
    return
  fi
  if vercel env add "$1" "${flags[@]}"; then
    printf '  %s✓ set%s %s (%s) on Vercel\n' "$GREEN" "$RESET" "$1" "$2"
  else
    SKIPPED+=("Vercel env $1 for $2 (add it in Project > Settings > Environment Variables)")
    warn "couldn't set $1 for $2 with the CLI; add it in the dashboard"
  fi
}

# until_ok "what" CMD... re-runs a check until it passes. Declining a retry offers to
# skip the check (recorded in the summary); declining that stops the wizard.
until_ok() {
  local what="$1"; shift
  until "$@"; do
    warn "$what did not pass yet."
    confirm "Fix it, then check again?" && continue
    if confirm "Skip this check and carry on?"; then
      SKIPPED+=("check: $what"); return 0
    fi
    say "Stopped. Re-run scripts/cutover.sh when it's fixed; saved values are kept."
    exit 1
  done
}

# secret_or_new KEY fills $KEY from .env.cutover, or generates a fresh 32-byte secret.
secret_or_new() {
  local current
  current=$(_existing "$1" || true)
  [[ -n "$current" ]] || current=$(openssl rand -base64 32)
  write_env "$1" "$current"
}

rollback_steps() {
  say "Rollback puts the old UI back on $PROD_URL. Its Render API and MongoDB are"
  say "still running until teardown (#10), so the old app works as before."
  printf '\n'
  step "1. Instant Rollback: in the project's Deployments tab, open the last old-UI"
  step "   production deployment, then ... > Instant Rollback. From the CLI:"
  note "     vercel rollback"
  note "   Hobby can only roll back to the previous production deployment, which right"
  note "   after cutover is the old UI${OLD_DEPLOYMENT:+ ($OLD_DEPLOYMENT)}."
  step "2. Rollback stops new production builds from taking cliplink.app. Once main is"
  step "   fixed, run 'vercel promote <deployment>' on the fixed build to resume."
  step "3. To keep building the old app, re-point the Git repo: Settings > Git >"
  step "   Disconnect, then connect ${OLD_REPO:-ososuna/cliplink-ui} again."
  step "4. Restore the old variables (only new builds of the old repo read them):"
  note "     values are in $BACKUP_FILE; for each one:"
  note "     vercel env add PUBLIC_API_BASE_URL --environment production --value '...' --yes"
  step "5. Sign-in on the old app still works: its Render callbacks are only removed"
  step "   in the last stage, after a passing smoke check."
}

stage_rollback() {
  stage "Roll back to the old deployment"
  roll_back
}

roll_back() {
  rollback_steps
  printf '\n'
  if command -v vercel >/dev/null 2>&1 && confirm "Run 'vercel rollback' now?"; then
    vercel rollback || warn "vercel rollback failed; use Instant Rollback in the dashboard"
  fi
  pause "Press Enter when $PROD_URL serves the old UI again."
}

run_wizard() {

cd "$(dirname "$0")/.."
ENV_FILE=".env.cutover"

if [[ "${1:-}" == rollback ]]; then
  TOTAL_STAGES=1
  OLD_DEPLOYMENT=$(_existing OLD_DEPLOYMENT || true)
  OLD_REPO=$(_existing OLD_REPO || true)
  stage_rollback
  printf '\n'
  return
fi

TOTAL_STAGES=14

banner "Cliplink: production setup and cutover to cliplink.app"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and the Vercel project"
say "This puts the new Cliplink live on $PROD_URL. Nothing changes for users until"
say "stage 12 (the merge to main). Every stage before that can be re-run."
printf '\n'
missing=()
for tool in vercel gh node pnpm openssl; do
  command -v "$tool" >/dev/null 2>&1 || missing+=("$tool")
done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}. Install them (Vercel CLI: npm i -g vercel@latest), then re-run."
  exit 1
fi
note "vercel $(vercel --version 2>/dev/null | tail -n1). The firewall commands need a recent CLI."
[[ -d node_modules ]] || { step "Installing dependencies"; pnpm install; }
until_ok "vercel whoami" vercel whoami
until_ok "gh auth status" gh auth status
step "Link this folder to the existing Vercel project, the one serving $PROD_URL"
step "(answer the prompts: your scope, link to existing project, pick it)."
if [[ -f .vercel/project.json ]] && ! confirm "Already linked. Link again?"; then :; else
  vercel link
fi
until_ok ".vercel/project.json exists" test -f .vercel/project.json
printf '\n'
step "Backing up the current production variables to $BACKUP_FILE (for rollback)."
if [[ -f "$BACKUP_FILE" ]]; then
  note "$BACKUP_FILE already exists, kept as is."
else
  if (umask 077 && vercel env pull "$BACKUP_FILE" --environment production --yes >/dev/null); then
    printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$BACKUP_FILE"
  else
    warn "backup failed; copy the PUBLIC_* values from the dashboard by hand"
  fi
fi
open_url "https://vercel.com/dashboard"
step "Open the project > Deployments, and copy the URL of the current production"
step "deployment (the old UI). Rollback goes back to it."
ask OLD_DEPLOYMENT "Current production deployment URL:"
write_env OLD_DEPLOYMENT "$OLD_DEPLOYMENT"
ask OLD_REPO "Repo the project deploys today (usually ososuna/cliplink-ui):"
write_env OLD_REPO "${OLD_REPO:-ososuna/cliplink-ui}"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google OAuth app, production"
say "A new OAuth client for cliplink.app. Keep the old one: it is removed in the"
say "last stage, so rollback still has working sign-in."
open_url "https://console.cloud.google.com/auth/clients"
step "Pick (or create) the Google Cloud project for Cliplink production."
step "Branding: app name Cliplink, home page $PROD_URL, privacy policy"
step "  $PROD_URL/privacy-policy, terms $PROD_URL/terms-of-service,"
step "  authorized domain cliplink.app."
step "Audience: External, and publish the app (In production), or only test users can sign in."
step "Clients > Create client > Web application, name 'Cliplink production'."
step "Authorized JavaScript origins: $PROD_URL"
step "Authorized redirect URIs: $PROD_URL/api/auth/callback/google"
step "Create, then copy the Client ID and the Client secret (the secret is shown once)."
ask PROD_GOOGLE_CLIENT_ID "Production Google Client ID:"
until [[ "$PROD_GOOGLE_CLIENT_ID" == *.apps.googleusercontent.com ]]; do
  warn "A Google Client ID ends in .apps.googleusercontent.com."
  ask PROD_GOOGLE_CLIENT_ID "Production Google Client ID:"
done
ask_secret PROD_GOOGLE_CLIENT_SECRET "Production Google Client secret:"
write_env PROD_GOOGLE_CLIENT_ID "$PROD_GOOGLE_CLIENT_ID"
write_env PROD_GOOGLE_CLIENT_SECRET "$PROD_GOOGLE_CLIENT_SECRET"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app, production"
say "A GitHub OAuth app has one callback URL, so production gets its own app."
open_url "https://github.com/settings/applications/new"
step "Application name: Cliplink"
step "Homepage URL: $PROD_URL"
step "Authorization callback URL: $PROD_URL/api/auth/callback/github"
step "Leave Enable Device Flow off, then Register application."
step "Copy the Client ID, then Generate a new client secret and copy it (shown once)."
ask PROD_GITHUB_CLIENT_ID "Production GitHub Client ID:"
ask_secret PROD_GITHUB_CLIENT_SECRET "Production GitHub Client secret:"
write_env PROD_GITHUB_CLIENT_ID "$PROD_GITHUB_CLIENT_ID"
write_env PROD_GITHUB_CLIENT_SECRET "$PROD_GITHUB_CLIENT_SECRET"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google OAuth app, development"
say "Local sign-in uses its own client, never the production one. Values go to .env."
ENV_FILE=".env"
if [[ ! -f .env ]]; then (umask 077 && cp .env.example .env); note "created .env from .env.example"; fi
open_url "https://console.cloud.google.com/auth/clients"
step "Clients > Create client > Web application, name 'Cliplink development'."
step "Authorized JavaScript origins: http://localhost:4321"
step "Authorized redirect URIs: http://localhost:4321/api/auth/callback/google"
step "Create, then copy the Client ID and Client secret."
note "While the app's Audience is in testing, add yourself as a test user."
ask GOOGLE_CLIENT_ID "Development Google Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Development Google Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
secret_or_new BETTER_AUTH_SECRET
ENV_FILE=".env.cutover"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app, development"
ENV_FILE=".env"
open_url "https://github.com/settings/applications/new"
step "Application name: Cliplink (development)"
step "Homepage URL: http://localhost:4321"
step "Authorization callback URL: http://localhost:4321/api/auth/callback/github"
step "Register application, copy the Client ID, then generate and copy a client secret."
ask GITHUB_CLIENT_ID "Development GitHub Client ID:"
ask_secret GITHUB_CLIENT_SECRET "Development GitHub Client secret:"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
note "Check it later with 'pnpm dev' and both sign-in buttons on http://localhost:4321."
ENV_FILE=".env.cutover"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel project: re-point it at $NEW_REPO"
say "Same project, so cliplink.app, Analytics and Speed Insights history stay."
say "Production deploys from main, which has no app yet: don't push to main before stage 12."
open_url "https://github.com/settings/installations"
step "Vercel > Configure > Repository access: make sure $NEW_REPO is included."
open_url "https://vercel.com/dashboard"
step "Open the project > Settings > Git > Connected Git Repository > Disconnect."
step "Connect Git Repository > GitHub > $NEW_REPO. Production branch: main."
step "Settings > Build and Deployment: Framework Preset Astro, Root Directory empty,"
step "  and every Override off (vercel.json sets the build command), Node.js 24.x."
step "Analytics and Speed Insights tabs: both still enabled."
note "Preview deploys of open PRs may fail until stage 9 sets the variables. That's fine."
pause "Press Enter when the project shows $NEW_REPO as its Git repository."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Neon through the Vercel Marketplace"
say "Free plan, one database branch per preview deploy (ADR-0001)."
open_url "https://vercel.com/marketplace/neon"
step "Install (or Add Database) on your account, plan Free, region Washington, D.C."
step "  (iad1, next to Vercel's default functions region)."
step "Connect it to the cliplink project with Production, Preview and Development"
step "  checked, no custom env var prefix (so it sets DATABASE_URL)."
step "Turn on a database branch per deployment for Preview."
pause "Press Enter when the database shows as connected to the project."
until_ok "Neon production variables" check_neon_env

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Migrate the production database"
say "Applies drizzle/ to the empty production branch (ADR-0004: no data to move)."
say "Every later deploy migrates too: vercel.json runs 'pnpm db:migrate' before the build."
prod_db=""
if file=$(pull_env production); then
  prod_db=$(grep -E '^DATABASE_URL_UNPOOLED=' "$file" | head -n1 | cut -d= -f2- | sed -e 's/^"//' -e 's/"$//')
fi
if [[ -z "$prod_db" ]]; then
  note "Vercel hides this value. In the Neon console: your project > Connect, production"
  note "branch, Connection pooling off, then copy the connection string."
  open_url "https://console.neon.tech"
  ask_secret prod_db "Production unpooled connection string (not saved):"
fi
if confirm "Run 'pnpm db:migrate' against production now?"; then
  DATABASE_URL_UNPOOLED="$prod_db" pnpm db:migrate
fi
until_ok "production migrations" env DATABASE_URL_UNPOOLED="$prod_db" node scripts/cutover/verify.ts migrations
unset prod_db

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Environment variables"
say "The build needs all six Better Auth variables (astro.config.mjs), in Production and"
say "Preview. Preview uses the development OAuth apps and its own secret: sign-in can't"
say "work on *.vercel.app previews (no callback registered), but anonymous create can."
secret_or_new PROD_BETTER_AUTH_SECRET
secret_or_new PREVIEW_BETTER_AUTH_SECRET
dev_google_id=$(ENV_FILE=.env _existing GOOGLE_CLIENT_ID || true)
dev_google_secret=$(ENV_FILE=.env _existing GOOGLE_CLIENT_SECRET || true)
dev_github_id=$(ENV_FILE=.env _existing GITHUB_CLIENT_ID || true)
dev_github_secret=$(ENV_FILE=.env _existing GITHUB_CLIENT_SECRET || true)
printf '\n'
note "Production: BETTER_AUTH_URL=$PROD_URL, BETTER_AUTH_SECRET, production OAuth apps."
note "Preview:    BETTER_AUTH_URL=$PROD_URL, its own secret, development OAuth apps."
note "Removed:    ${LEGACY_VARS[*]} (all environments)."
if confirm "Write these to the Vercel project?"; then
  vercel_env BETTER_AUTH_URL production "$PROD_URL"
  vercel_env BETTER_AUTH_SECRET production "$PROD_BETTER_AUTH_SECRET" sensitive
  vercel_env GOOGLE_CLIENT_ID production "$PROD_GOOGLE_CLIENT_ID"
  vercel_env GOOGLE_CLIENT_SECRET production "$PROD_GOOGLE_CLIENT_SECRET" sensitive
  vercel_env GITHUB_CLIENT_ID production "$PROD_GITHUB_CLIENT_ID"
  vercel_env GITHUB_CLIENT_SECRET production "$PROD_GITHUB_CLIENT_SECRET" sensitive
  vercel_env BETTER_AUTH_URL preview "$PROD_URL"
  vercel_env BETTER_AUTH_SECRET preview "$PREVIEW_BETTER_AUTH_SECRET" sensitive
  vercel_env GOOGLE_CLIENT_ID preview "$dev_google_id"
  vercel_env GOOGLE_CLIENT_SECRET preview "$dev_google_secret" sensitive
  vercel_env GITHUB_CLIENT_ID preview "$dev_github_id"
  vercel_env GITHUB_CLIENT_SECRET preview "$dev_github_secret" sensitive
  for name in "${LEGACY_VARS[@]}"; do
    if vercel env rm "$name" --yes; then
      printf '  %s✓ removed%s %s\n' "$GREEN" "$RESET" "$name"
    else
      note "$name: not removed (maybe it was never set)"
    fi
  done
fi
until_ok "production variables" check_env production
until_ok "preview variables" check_env preview

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Rate limit: one Vercel WAF rule"
say "Anonymous Link creation, 30 requests per minute per IP, fixed window. Hobby allows"
say "one rate limit rule per project. It matches POSTs to /_actions/links.create, the"
say "create Action, when the request has no session cookie."
printf '\n'
warn "Trade-off: the WAF can only see whether the session cookie exists, not whether"
warn "it is valid. A script that sends any cookie with that name skips the limit."
note "Limiting every create instead closes that gap, but also limits signed-in Users"
note "(30 per minute per IP is far above human use). The spec asks for anonymous only."
scope="anonymous"
conditions=(
  --condition '{"type":"path","op":"pre","value":"/_actions/links.create"}'
  --condition '{"type":"method","op":"eq","value":"POST"}'
)
if confirm "Limit every create instead, signed-in Users included?"; then
  scope="every-create"
else
  conditions+=(--condition '{"type":"cookie","key":"__Secure-better-auth.session_token","op":"nex"}')
fi
if confirm "Add the rule now with the Vercel CLI?"; then
  vercel firewall rules add "Anonymous Link creation" "${conditions[@]}" \
    --description "Anonymous Link creation: 30 per minute per IP (spec #1)" \
    --action rate_limit --rate-limit-window 60 --rate-limit-requests 30 \
    --rate-limit-keys ip --rate-limit-algo fixed_window --yes \
    || warn "rules add failed; create it in the dashboard (below)"
  vercel firewall diff || true
  step "Publishing: the CLI lists the staged change and asks you to confirm."
  vercel firewall publish || warn "publish failed; publish it in the dashboard"
else
  open_url "https://vercel.com/dashboard"
  step "Project > Firewall > Configure > New Rule, name 'Anonymous Link creation'."
  step "If Request Path starts with /_actions/links.create, and Method equals POST"
  [[ "$scope" == anonymous ]] && step "  and Cookie __Secure-better-auth.session_token does not exist,"
  step "Then Rate Limit: Fixed Window, 60 seconds, 30 requests, key IP, action Too Many Requests."
  step "Save, then Review Changes > Publish."
fi
vercel firewall rules list --expand || true
pause "Press Enter when the rule shows as published (not a draft)."
note "Optional check: 31 invalid creates from this IP (no Link is created), then one"
note "with a fake session cookie. Your IP can't create Links for up to a minute after."
if confirm "Run the check now?"; then
  until_ok "rate limit probe" verify rate-limit "$PROD_URL" "$scope"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Last checks before cutover"
say "After the merge, $PROD_URL serves the new app with an empty database: every old"
say "Code returns 404 (ADR-0004). Cliplink stays non-commercial on Hobby (ADR-0002)."
printf '\n'
until_ok "production variables" check_env production
pr_url=$(gh pr view "$SPEC_BRANCH" -R "$NEW_REPO" --json url -q .url 2>/dev/null || true)
pr_url=${pr_url:-https://github.com/$NEW_REPO/compare/main...$SPEC_BRANCH}
step "CI on the PR must be green:"
gh pr checks "$SPEC_BRANCH" -R "$NEW_REPO" || warn "CI is not green (or there's no PR yet)."
step "Rollback, if the smoke check fails, is: Instant Rollback to $OLD_DEPLOYMENT"
step "(or scripts/cutover.sh rollback). The next stages walk you through it."
pause "Press Enter when ready to merge."

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Cutover: merge to main"
open_url "$pr_url"
step "Mark the PR ready for review if it is a draft, then merge it into main."
step "Vercel builds main: it migrates production, builds, and assigns cliplink.app."
pause "Press Enter once it is merged."
say "Waiting for $PROD_URL to serve the new app (Ctrl-C to stop)."
for _ in $(seq 1 60); do
  verify live "$PROD_URL" >/dev/null 2>&1 && break
  printf '.'; sleep 10
done
printf '\n'
until_ok "new app on $PROD_URL" verify live "$PROD_URL"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Production smoke check"
say "In a private window (signed out):"
open_url "$PROD_URL"
smoke_ok=1
destination="https://example.com/cliplink-smoke-$(date +%s)"
step "Anonymous create: paste $destination into Long URL and shorten it."
ask short_url "Paste the short URL it gives you:"
verify redirect "$short_url" "$destination" || smoke_ok=0
step "Open the short URL: it should land on example.com."
step "Sign in with Google: you land on /dashboard with your name. Then sign out."
confirm "Google sign-in worked?" || smoke_ok=0
step "Sign in with GitHub: you land on /dashboard with your name."
confirm "GitHub sign-in worked?" || smoke_ok=0
if (( ! smoke_ok )); then
  warn "The smoke check failed. Roll back now, fix it on a branch, then re-run stage 11 on."
  pause "Press Enter for the rollback steps."
  _clear
  roll_back
  exit 1
fi
printf '  %s✓ smoke check passed%s\n' "$GREEN" "$RESET"
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Remove the old Render callbacks"
warn "After this, rolling back leaves the old UI without sign-in. Do it when you are"
warn "happy with the new app."
if confirm "Remove the old callbacks now?"; then
  open_url "https://console.cloud.google.com/auth/clients"
  step "Open the old OAuth client and delete every redirect URI on onrender.com"
  step "(delete the client if it has nothing else). Save."
  open_url "https://github.com/settings/developers"
  step "Open the old OAuth app with the onrender.com callback and delete it."
  pause "Press Enter when both are gone."
else
  SKIPPED+=("remove the old Render callbacks from Google and GitHub (re-run, or do it by hand)")
fi
note "Keep $BACKUP_FILE until the teardown (#10), one week from now."
note ".env.cutover holds production secrets. Delete it once they're safe in Vercel."

finish
}

run_wizard "$@"; exit
